/**
 * PBKDF2 keystream object, a faithful port of Dwayne Litzenberger's
 * `pbkdf2` module (the one the original Python script imports).
 *
 * The class is NOT a one-shot key-derivation function: it is a readable
 * stream of key material. `read(n)` hands back the next `n` octets,
 * remembering any leftover bytes of the last generated block so that
 * `read(10)` twice yields exactly the same octets as `read(20)` once.
 */

import sha1 from './hash/sha1.mjs';
import * as hmac from './hash/hmac.mjs';
import { toHex, xorInto, concatBytes, uint32be } from './bytes.mjs';
import { encodeUtf8Strict } from './pycodec.mjs';
