/**
 * Line numbers inside the upstream `pbkdf2.py`. The compiled binary still
 * reports them in tracebacks, so failures raised during `_setup` carry the
 * matching `frameLine` for the traceback renderer.
 */
const LINE_ENCODE_PASSPHRASE = 193;
const LINE_ENCODE_SALT = 197;
const LINE_ITERATIONS_CHECK = 205;

/** Largest block index PBKDF2 can address: the counter is a 32-bit BE int. */
const MAX_BLOCK_INDEX = 0xffffffff;

/**
