   * @param {string|Uint8Array} salt encoded as UTF-8 when it is a string
   * @param {number} [iterations=1000] must be >= 1
   * @param {object} [digestmodule=sha1] hashlib-like module (digest_size, block_size, create)
   * @param {object} [macmodule=hmac] hmac-like module exposing `create`
   */
  constructor(passphrase, salt, iterations = 1000, digestmodule = sha1, macmodule = hmac) {
    this._buf = new Uint8Array(0);
    this._blockNum = 0;
    this._closed = false;
    this._digestmodule = digestmodule;
    this._macmodule = macmodule;
    // Pre-keyed MAC used as a clone source; created lazily on first read.
    this._macBase = null;

    this._setup(passphrase, salt, iterations);
  }

  /**
   * Sanity checks and encoding, in the exact order the Python module performs
   * them: passphrase, then salt, then the iteration-count check. The order is
   * observable because each step raises from a different source line.
   */
  _setup(passphrase, salt, iterations) {
    // 1. passphrase -> bytes (pbkdf2.py:193)
    let passphraseBytes;
    if (passphrase instanceof Uint8Array) {
      passphraseBytes = passphrase;
    } else {
      try {
        passphraseBytes = encodeUtf8Strict(passphrase);
      } catch (err) {
        if (err instanceof PyUnicodeEncodeError) err.frameLine = LINE_ENCODE_PASSPHRASE;
        throw err;
      }
    }

    // 2. salt -> bytes (pbkdf2.py:197)
    let saltBytes;
    if (salt instanceof Uint8Array) {
      saltBytes = salt;
    } else {
      try {
        saltBytes = encodeUtf8Strict(salt);
      } catch (err) {
        if (err instanceof PyUnicodeEncodeError) err.frameLine = LINE_ENCODE_SALT;
        throw err;
      }
    }

    // 3. iterations must be at least 1 (pbkdf2.py:205). Python compares the
    // integer directly; a plain numeric comparison reproduces that.
    if (iterations < 1) {
      const err = new PyValueError('iterations must be at least 1');
      err.frameLine = LINE_ITERATIONS_CHECK;
      throw err;
    }

    this._passphrase = passphraseBytes;
    this._salt = saltBytes;
    this._iterations = iterations;
  }

  /**
   * Pseudorandom function, i.e. HMAC-SHA1 keyed with the passphrase.
   * The passphrase never changes, so the inner/outer padded hash states are
   * computed once and cloned per call instead of being re-derived.
   */
  _prf(msg) {
    if (this._macBase === null) {
      this._macBase = newMac(this._macmodule, this._passphrase, null, this._digestmodule);
    }
    if (typeof this._macBase.copy === 'function') {
      const mac = this._macBase.copy();
      mac.update(msg);
      return mac.digest();
    }
    // Fallback for a macmodule whose objects are not cloneable.
    return newMac(this._macmodule, this._passphrase, msg, this._digestmodule).digest();
  }

  /**
   * F(i) = U1 ^ U2 ^ ... ^ Uc, with U1 = PRF(salt || BE32(i))
   * and Uj = PRF(U(j-1)).
   */
  _f(i) {
    let u = this._prf(concatBytes([this._salt, uint32be(i)]));
    const result = u.slice();
    for (let j = 2; j <= this._iterations; j += 1) {
      u = this._prf(u);
      xorInto(result, u);
    }
    return result;
  }

  /**
   * Read the next `n` octets of key material.
   * @param {number} n
   * @returns {Uint8Array}
   */
  read(n) {
    if (this._closed) throw new PyValueError('file-like object is closed');

    let size = this._buf.length;
    const blocks = [this._buf];
    let i = this._blockNum;
    while (size < n) {
      i += 1;
      if (i > MAX_BLOCK_INDEX) throw new PyError('OverflowError', 'derived key too long');
      const block = this._f(i);
      blocks.push(block);
      size += block.length;
    }

    const buf = concatBytes(blocks);
    const retval = buf.slice(0, n);
    this._buf = buf.slice(n);
    this._blockNum = i;
    return retval;
  }

  /**
   * Read `octets` bytes and return them as lowercase hex.
   * @param {number} octets
   * @returns {string}
   */
  hexread(octets) {
    return toHex(this.read(octets));
  }

  /** Close the stream and drop the key material. */
  close() {
    if (!this._closed) {
      this._passphrase = null;
      this._salt = null;
      this._iterations = null;
      this._macBase = null;
      this._buf = null;
      this._closed = true;
    }
  }

  /** @returns {boolean} */
  get closed() {
    return this._closed;
  }
}

export default PBKDF2;

export function toHex(u8) {
  let s = '';
  for (let i = 0; i < u8.length; i += 1) s += u8[i].toString(16).padStart(2, '0');
  return s;
}
export function xorInto(dst, src) {
  for (let i = 0; i < dst.length; i += 1) dst[i] ^= src[i];
