  return new Uint8Array([(n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff]);
}
export function bytesEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) if (a[i] !== b[i]) return false;
  return true;
}

export class PyError extends Error {
  constructor(type, message) {
    super(message);
    this.pyType = type;
    this.pyMessage = message;
  }
}
export class PyValueError extends PyError {
  constructor(message) { super('ValueError', message); }
}
export class PyUnicodeEncodeError extends PyError {
  constructor(codePoint, position) {
    const esc = '\\u' + codePoint.toString(16).padStart(4, '0');
    super('UnicodeEncodeError',
      `'utf-8' codec can't encode character '${esc}' in position ${position}: surrogates not allowed`);
    this.frameLine = null;
  }
}
