import { execFileSync } from 'node:child_process';
import { PBKDF2 } from './lib/pbkdf2.mjs';
import { toHex } from './lib/bytes.mjs';
import { PyValueError, PyUnicodeEncodeError, PyError } from './lib/pyerror.mjs';
import sha1, { SHA1 } from './lib/hash/sha1.mjs';

const EXE = '/workspace/dataset/test2_executable';
let pass = 0;
let fail = 0;
function check(name, got, want) {
  if (got === want) { pass += 1; }
  else { fail += 1; console.log(`FAIL ${name}\n  got  ${got}\n  want ${want}`); }
}

// --- SHA-1 stub sanity (so failures below are attributable to pbkdf2.mjs) ---
check('sha1("abc")', toHex(sha1.create(new TextEncoder().encode('abc')).digest()),
  'a9993e364706816aba3e25717850c26c9cd0d89d');
check('sha1("")', toHex(new SHA1().digest()), 'da39a3ee5e6b4b0d3255bfef95601890afd80709');

// --- RFC 6070 vectors ---
const rfc = [
  ['password', 'salt', 1, 20, '0c60c80f961f0e71f3a9b524af6012062fe037a6'],
  ['password', 'salt', 2, 20, 'ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957'],
  ['password', 'salt', 4096, 20, '4b007901b765489abead49d926f721d065a429c1'],
  ['passwordPASSWORDpassword', 'saltSALTsaltSALTsaltSALTsaltSALTsalt', 4096, 25,
    '3d2eec4fe41c849b80c8d83662c0e44a8b291a964cf2f07038'],
  ['pass\0word', 'sa\0lt', 4096, 16, '56fa6aa75548099dcc37d7f03425e0c3'],
