// --- Streaming property ---
{
  const one = toHex(new PBKDF2('password', 'salt', 100).read(20));
  const st = new PBKDF2('password', 'salt', 100);
  const two = toHex(st.read(10)) + toHex(st.read(10));
  check('read(10)+read(10) === read(20)', two, one);

  const forty = toHex(new PBKDF2('password', 'salt', 100).read(40));
  const st2 = new PBKDF2('password', 'salt', 100);
  const split = toHex(st2.read(25)) + toHex(st2.read(15));
  check('read(25)+read(15) === read(40)', split, forty);

