  check('pw before salt', grab(() => new PBKDF2(bad, bad, 10)).frameLine, 193);
  check('pw before iter', grab(() => new PBKDF2(bad, 's', 0)).frameLine, 193);
  check('salt before iter', grab(() => new PBKDF2('p', bad, 0)).frameLine, 197);
}

