  st.read(4);
  st.close();
  check('closed true', st.closed, true);
  st.close(); // idempotent
  const e = grab(() => st.read(1));
  check('read after close type', e && e.pyType, 'ValueError');
  check('read after close msg', e && e.pyMessage, 'file-like object is closed');
