{
  const t0 = Date.now();
  new PBKDF2('=BH[kuEw', 'salt_740344', 10000).read(20);
  const ms = Date.now() - t0;
  console.log(`perf: 10000 iterations in ${ms} ms`);
  check('perf < 500ms', ms < 500, true);
}

